// v160: 🍺 avisos da cervejeira — temperatura parada no mesmo valor há mais de 1 h (sensor travado) e motor ligado direto há mais de 2 h.
// Caso de 26/11/2026: o sensor travou em 4,3 °C às 00:41 e o motor ficou ligado sem parar até as 10:18. Repete a cada 1 h enquanto durar.
function cervSensor_() {
  var props = PropertiesService.getScriptProperties(), ag = Date.now(), sh = SpreadsheetApp.getActive().getSheetByName(ABA_CTEMP), n = sh ? sh.getLastRow() : 0; if (n < 3) return;
  var ini = Math.max(2, n - 170), c = []; // ~2h50 de leituras (container + cervejeira, uma de cada a cada 2 min)
  sh.getRange(ini, 1, n - ini + 1, 12).getValues().forEach(function (l) { if (String(l[1]) === 'CERV' && l[2] !== '' && Number(l[11])) c.push([Number(l[11]), Number(l[2]), l[3] === 'LIGADO']); });
  if (!c.length || ag - c[c.length - 1][0] > 10 * 60000) return; // sem leitura recente não dá para dizer nada
  var u = c[c.length - 1], i = c.length - 1, j = c.length - 1;
  while (i > 0 && c[i - 1][1] === u[1]) i--;
  while (u[2] && j > 0 && c[j - 1][2]) j--;
  var minP = (u[0] - c[i][0]) / 60000, qP = c.length - i, minM = u[2] ? (u[0] - c[j][0]) / 60000 : 0, qM = c.length - j;
  var avisa = function (k, sim, tit, tx) { if (!sim) { props.deleteProperty(k); return; } if (ag - Number(props.getProperty(k) || 0) < 60 * 60000) return; props.setProperty(k, String(ag)); contPush_(tit, tx); };
  avisa('CERV_AV_PARADA', minP >= 60 && qP >= 20, '🍺 Cervejeira: temperatura parada em ' + contFmt_(u[1]) + ' °C há mais de 1 hora', 'O sensor pode ter travado · motor ' + (u[2] ? 'LIGADO' : 'desligado') + '. Confira as cervejas e tire o controlador da tomada por 30 segundos.');
  avisa('CERV_AV_MOTOR', minM >= 120 && qM >= 40, '🍺 Cervejeira: motor ligado direto há mais de 2 horas', 'Temperatura em ' + contFmt_(u[1]) + ' °C e o motor não desligou nenhuma vez. Pode ser sensor travado, porta aberta ou muita mercadoria quente.');
}
